(function () {
  var old = document.getElementById('nb-qr-dialog');
  if (old) old.remove();
  var name = (ctx.record && (ctx.record.name || ctx.record.title)) || '';
  var wrap = document.createElement('div');
  wrap.id = 'nb-qr-dialog';
  wrap.style.cssText = 'position:fixed;inset:0;z-index:99999;background:rgba(0,0,0,0.45);display:flex;align-items:center;justify-content:center;';
  var card = document.createElement('div');
  card.style.cssText = 'position:relative;background:#fff;border-radius:8px;padding:16px;box-shadow:0 8px 32px rgba(0,0,0,0.25);';
  var bar = document.createElement('div');
  bar.style.cssText = 'display:flex;align-items:center;justify-content:space-between;gap:16px;margin-bottom:8px;';
  var t = document.createElement('span');
  t.textContent = '报名二维码' + (name ? ' - ' + name : '');
  t.style.cssText = 'font-weight:600;font-size:15px;color:rgba(0,0,0,0.88);';
  var close = document.createElement('button');
  close.textContent = '关闭';
  close.style.cssText = 'border:1px solid #d9d9d9;border-radius:6px;background:#fff;padding:4px 12px;cursor:pointer;';
  var frame = document.createElement('iframe');
  frame.src = '/x/main/qr?class=' + ctx.record.id;
  frame.style.cssText = 'width:480px;height:620px;border:0;display:block;';
  close.addEventListener('click', function () { wrap.remove(); });
  wrap.addEventListener('click', function (e) { if (e.target === wrap) wrap.remove(); });
  bar.appendChild(t);
  bar.appendChild(close);
  card.appendChild(bar);
  card.appendChild(frame);
  wrap.appendChild(card);
  document.body.appendChild(wrap);
})();
